def path(d: str) -> QPainterPath:
    """A QPainterPath from absolute M, L, C and Z commands."""
    out = QPainterPath()
    for cmd, args in re.findall(r"([MLCZ])([^MLCZ]*)", d):
        v = [float(x) for x in args.split()]
        if cmd == "M":
            out.moveTo(v[0], v[1])
        elif cmd == "L":
            out.lineTo(v[0], v[1])
        elif cmd == "C":
            out.cubicTo(QPointF(v[0], v[1]), QPointF(v[2], v[3]), QPointF(v[4], v[5]))
        else:
            out.closeSubpath()
    return out


def _svg_for(px: int) -> str:
    """The drawing made for this size: the nearest small one at or above
    it, or the full logo past 48 px."""
    for size in sorted(SMALL):
        if px <= size:
            return SMALL[size]
    return LOGO


def render(svg: str, px: int) -> QImage:
    img = QImage(px, px, QImage.Format.Format_ARGB32_Premultiplied)
    img.fill(Qt.GlobalColor.transparent)
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    QSvgRenderer(QByteArray(svg.encode())).render(p)
    p.end()
    return img


def icon_pixmap(px: int) -> QPixmap:
    """The icon at `px` device pixels, drawn from the version made for it."""
    return QPixmap.fromImage(render(_svg_for(px), px))


def bare_pixmap(px: int) -> QPixmap:
    """The icon without its tile: only crescent, crest, eye and beak, for
    places that have a background of their own, such as the title bar."""
    svg = re.sub(r'<path d="[^"]*" style="fill:(?:url\(#_Linear1\)|#3a3b40)[^"]*"/>',
                 "", _svg_for(px))
    return QPixmap.fromImage(render(svg, px))


def app_icon() -> QIcon:
    icon = QIcon()
    for px in (16, 24, 32, 48, 64, 128, 256):
        icon.addPixmap(icon_pixmap(px))
    return icon
